//! Parity tests for `Number`, `Boolean`, and `Math`: each program's result must equal what upstream
//! `@opencode/codemode` (running on Bun/JavaScriptCore) printed for it. Cases are ported from the upstream stdlib,
//! parity, callbacks, generator, and regexp-math Test262 suites, plus probes of formatting, receivers, coercion order,
//! host error texts, the libm-backed functions, `hypot`/`pow`/`round`, and `sumPrecise` (sampled from fuzzing
//! against the host).

#[path = "common/dump.rs"]
mod dump;

use std::sync::Arc;

use oc_codemode::codemode::{CodeMode, ExecutionLimits};
use oc_codemode::host::NoTools;
use serde_json::Value as Json;

/// JSON equality with numbers compared as doubles (an integral result may be an integer or a float).
fn same(a: &Json, b: &Json) -> bool {
    match (a, b) {
        (Json::Number(x), Json::Number(y)) => x.as_f64() == y.as_f64(),
        (Json::Array(x), Json::Array(y)) => x.len() == y.len() && x.iter().zip(y).all(|(p, q)| same(p, q)),
        (Json::Object(x), Json::Object(y)) => {
            x.len() == y.len() && x.iter().zip(y.iter()).all(|((k, v), (l, w))| k == l && same(v, w))
        }
        _ => a == b,
    }
}

/// Runs every `(program, upstream result JSON)` pair and reports all mismatches at once.
fn check(cases: &[(&str, &str)]) {
    let runtime = CodeMode::new(Vec::new(), Arc::new(NoTools), Vec::new(), ExecutionLimits::default()).unwrap();
    let mut failures = Vec::new();
    for (code, expected) in cases {
        dump::case("stdlib_number", code, expected);
        let actual = runtime.execute_blocking(code).to_json();
        let expected: Json = serde_json::from_str(expected).expect("expected JSON");
        if !same(&actual, &expected) {
            failures.push(format!("program: {code}\n  expected: {expected}\n  actual:   {actual}"));
        }
    }
    assert!(failures.is_empty(), "{} of {} cases differ:\n\n{}", failures.len(), cases.len(), failures.join("\n\n"));
}

